import{z as o,x as t,o as r,c as d,q as A,j as i,D as e,d as E,s as n,S as B,b as s}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"模糊测试的深入","description":"","frontmatter":{"title":"模糊测试的深入","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ss-fuzzing-deep.md","filePath":"cs/ss-fuzzing-deep.md","lastUpdated":1791063341000}'),c={name:"cs/ss-fuzzing-deep.md"};function p(f,a,D,u,h,z){const l=t("Mermaid");return r(),d("div",null,[a[2]||(a[2]=A('<h1 id="模糊测试的深入" tabindex="-1">模糊测试的深入 <a class="header-anchor" href="#模糊测试的深入" aria-label="Permalink to &quot;模糊测试的深入&quot;">​</a></h1><div class="epigraph"><p>模糊测试的赌注是：bug 在输入空间里不是均匀分布的，而覆盖率反馈能把随机行走变成有梯度的爬山；梯度的尽头，才是方法开始的地方。</p><footer>—— 据 Zalewski, AFL；Manès et al., The Art, Science, and Engineering of Fuzzing, TSE 2019 整理</footer></div><p><a href="/cs/ss-supply-chain">上一课</a>把「代码从哪来」钉成站点图，xz 一案顺带留了一个注脚：fuzzing 没抓到它，因为它没跑在 sshd 上。本课深钻 fuzzing 本身。主干已有<a href="/cs/coverage-guided-fuzzing">覆盖引导模糊测试</a>（AFL 的反馈回路）、<a href="/cs/sanitizers">sanitizer</a>（崩溃预言）、<a href="/cs/symbolic-execution">符号执行</a>与<a href="/cs/compiler-fuzzing">编译器模糊测试</a>；缺口是从「跑一个 fuzzer」到「经营一场战役」的方法：覆盖率走平之后，靠什么继续推进。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>覆盖率反馈回路有三个失效模式。浅路径饱和：解析器前面百分之几的分支吃掉全部能量，深层结构永远够不着；种子语料里没有合法样例，变异产物全死在第一道校验。状态化目标没有单入口：协议实现与内核不收「一个文件」，收的是「一个合法的调用序列」，变异单输入无从谈起。oracle 盲区：预言机只认崩溃，<a href="/cs/ss-kernel-vuln-classes">内核漏洞类别</a>里不崩溃的逻辑类与信息泄漏类，跑多久都是零报告。三个失效对应四种推进手段，加一项战役经营。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="语法、定向、提速与内核目标" tabindex="-1">语法、定向、提速与内核目标 <a class="header-anchor" href="#语法、定向、提速与内核目标" aria-label="Permalink to &quot;语法、定向、提速与内核目标&quot;">​</a></h3><p>结构感知：把变异约束在语法有效域内，或从种子语料反学语法（Godefroid 等的 Learn&amp;Fuzz 路线），让第一道校验不再是全程的瓶颈。定向：不是均匀撒能量，而是按「到目标代码的距离」分配——已知某补丁附近有洞、审计标出了可疑函数时，定向灰盒（AFLGo 路线）把爬山推向指定山坡。提速：进程内持久模式省掉 fork，每秒执行数抬高数量级；fuzzing 的产出以每秒执行数乘以时长计，速度本身就是深度。内核目标：syzkaller 把 syscall 序列写成可变异的微型程序，配上 KASAN 这类检测器当 oracle——<a href="/cs/ss-kernel-vuln-classes">内核类别表</a>的空间、时间与未初始化类，恰好都是内存检测器看得见的崩溃。</p><p><span class="marginnote">战役经营的四件套：语料最小化去掉等价输入；崩溃去重先用栈哈希初筛、再人工归并根因——同一根因常报出几十条不同栈；能量调度把饱和目标降权；检测器全套打开（ASan/KASAN），否则崩了也看不见。</span></p><p><span class="marginnote">数字实例：产出按「每秒执行数 × 时长」计——fork 每次冷启动约 100 次/秒时，24 小时只试了约 860 万个输入；换持久模式做到 1000 次/秒，同样 24 小时约 8600 万个，深度差一个数量级，这就是「速度本身就是深度」的算法。</span></p>',10)),(r(),i(B,null,{default:e(()=>[n(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEED%5B%22%E8%AF%AD%E6%96%99%EF%BC%9A%E6%9C%80%E5%B0%8F%E5%8C%96%E5%90%8E%E7%9A%84%E7%A7%8D%E5%AD%90%E9%9B%86%22%5D%20--%3E%20GEN%5B%22%E5%8F%98%E5%BC%82%20%2F%20%E8%AF%AD%E6%B3%95%E7%94%9F%E6%88%90%22%5D%0A%20%20GEN%20--%3E%20EXEC%5B%22%E8%BF%9B%E7%A8%8B%E5%86%85%E6%89%A7%E8%A1%8C%EF%BC%9A%E6%8C%81%E4%B9%85%E6%A8%A1%E5%BC%8F%22%5D%0A%20%20EXEC%20--%3E%20COV%5B%22%E8%A6%86%E7%9B%96%E7%8E%87%E5%8F%8D%E9%A6%88%22%5D%0A%20%20COV%20--%3E%20SEED%0A%20%20EXEC%20--%3E%20ORC%5B%22oracle%EF%BC%9AASan%20%2F%20KASAN%20%2F%20%E6%96%AD%E8%A8%80%22%5D%0A%20%20ORC%20--%3E%20CRASH%5B%22%E5%B4%A9%E6%BA%83%E6%A0%B7%E6%9C%AC%22%5D%0A%20%20CRASH%20--%3E%20DED%5B%22%E5%8E%BB%E9%87%8D%E4%B8%8E%E6%A0%B9%E5%9B%A0%E5%BD%92%E5%B9%B6%22%5D%0A%20%20DED%20--%3E%20FIX%5B%22%E4%BF%AE%E5%A4%8D%E5%B9%B6%E5%9B%9E%E6%94%B6%E6%96%B0%E7%A7%8D%E5%AD%90%22%5D%0A%20%20FIX%20--%3E%20SEED%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[E("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,[E("把框架拆开看：fuzzer 是输入采样器加 oracle。覆盖率反馈改变采样分布，让深路径从「指数概率」变成「有梯度可达」；oracle 决定能发现哪一类根因，与"),s("a",{href:"/cs/ss-kernel-vuln-classes"},"类别表"),E("逐格对齐——内存类有现成预言机，逻辑类没有，这就是 fuzzing 的硬边界，也是 xz 那类定向后门能穿过的缝。反过来，oracle 也在升级：把「不该发生」写成断言（不变量、差分对比、与参考实现互检），就是把逻辑类一格一格搬进可检测集合。无崩溃不等于无洞，等于「当前 oracle 看不见的类别无洞」——这句话是本课与第 1 课之间的合同。")],-1)),(r(),i(B,null,{default:e(()=>[n(l,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20F1%5B%22%E5%A4%B1%E6%95%88%E4%B8%80%3A%20%E6%B5%85%E8%B7%AF%E5%BE%84%E9%A5%B1%E5%92%8C%22%5D%20--%3E%20R1%5B%22%E8%AF%AD%E6%B3%95%E7%BB%93%E6%9E%84%E6%84%9F%E7%9F%A5%20%2F%20%E8%83%BD%E9%87%8F%E8%B0%83%E5%BA%A6%E9%99%8D%E6%9D%83%22%5D%0A%20%20F2%5B%22%E5%A4%B1%E6%95%88%E4%BA%8C%3A%20%E7%8A%B6%E6%80%81%E5%8C%96%E7%9B%AE%E6%A0%87%E6%97%A0%E5%8D%95%E5%85%A5%E5%8F%A3%22%5D%20--%3E%20R2%5B%22syzkaller%3A%20syscall%20%E5%BA%8F%E5%88%97%E5%BD%93%E8%BE%93%E5%85%A5%22%5D%0A%20%20F3%5B%22%E5%A4%B1%E6%95%88%E4%B8%89%3A%20oracle%20%E7%9B%B2%E5%8C%BA%22%5D%20--%3E%20R3%5B%22%E5%86%99%E6%96%AD%E8%A8%80%20%2F%20%E5%B7%AE%E5%88%86%E5%AF%B9%E6%AF%94%E5%BD%93%E6%96%B0%20oracle%22%5D%0A%20%20F1%20--%3E%20R4%5B%22%E5%AE%9A%E5%90%91%3A%20%E6%8C%89%E5%88%B0%E7%9B%AE%E6%A0%87%E8%B7%9D%E7%A6%BB%E5%88%86%E9%85%8D%E8%83%BD%E9%87%8F%22%5D%0A%20%20R1%20--%3E%20GOAL%5B%22%E8%A6%86%E7%9B%96%E7%8E%87%E8%B5%B0%E5%B9%B3%E5%90%8E%E7%BB%A7%E7%BB%AD%E6%8E%A8%E8%BF%9B%22%5D%0A%20%20R2%20--%3E%20GOAL%0A%20%20R3%20--%3E%20GOAL%0A%20%20R4%20--%3E%20GOAL%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=A('<p><span class="marginnote">直觉类比：覆盖率反馈像摸黑爬山——随机变异是在平原上乱走，覆盖率反馈是每走一步感觉一下坡度、只往变高的方向多踩几脚；走平了不是山没了，是该换个山坡（定向）或换双鞋（语法/提速）。</span></p><p><span class="marginnote">常见误区：初学者容易以为「换个更强的 fuzzer」就有产出。实际产出 = 每秒执行数 × 时长 × oracle 可见类别——三样缺一样都是零：没有 ASan/KASAN，内存坏了也不崩；只跑一小时，再快的采样器也到不了深路径。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>符号执行与污点分析作为向导的机制专课已讲，本课只用其结论；不写针对具体 CVE 的 harness 构造；执行速度的基准测量方法论不展开。内核目标的部署细节（syzkaller 的描述语言与复现格式）属于工具手册，不进本课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>覆盖率回路的三个失效：浅路径饱和、状态化目标无单入口、oracle 盲区。</li><li>四种推进：语法结构感知、定向能量分配、持久模式提速、syzkaller 式序列目标。</li><li>fuzzer 是采样器加 oracle；oracle 的覆盖与内核类别表逐格对齐，逻辑类是硬边界。</li><li>战役经营重于工具选择：语料最小化、崩溃归并、能量调度、检测器全开。</li><li>出处：Zalewski, AFL；Manès et al., TSE 2019；Godefroid et al., 2017；Böhme et al., 2017；对照 <a href="/cs/coverage-guided-fuzzing">coverage-guided-fuzzing</a>、<a href="/cs/sanitizers">sanitizers</a>。</li></ul>',6))])}const g=o(c,[["render",p]]);export{m as __pageData,g as default};
